import {
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import type { GenerateExtendingConfigFilesArgs } from '@teambit/workspace-config-files';
import { OxlintConfigWriter } from './oxlint-config-writer.js';

it('copies the full JSONC config so root-only options remain active', () => {
  const tempDir = mkdtempSync(path.join(tmpdir(), 'oxlint-config-writer-'));
  try {
    const configPath = path.join(tempDir, '.oxlintrc.jsonc');
    const source = `{
  // this comment verifies JSONC is preserved
  "plugins": ["typescript"],
  "options": { "typeAware": true }
}`;
    writeFileSync(configPath, source);
    const writer = new OxlintConfigWriter('OxlintConfigWriter', configPath);
    const [configFile] = writer.calcConfigFiles();
    const generated = writer.generateExtendingFile({
      writtenConfigFiles: [
        { ...configFile, hash: configFile.hash || '', filePath: configPath },
      ],
      workspaceDir: tempDir,
      configsRootDir: tempDir,
      envMapValue: {} as never,
    } satisfies GenerateExtendingConfigFilesArgs);

    expect(configFile.content).toBe(source);
    expect(generated?.content).toContain('"typeAware": true');
    expect(generated?.content).toContain('this comment verifies JSONC');
    expect(generated?.content).not.toContain('"extends"');

    const generatedPath = path.join(tempDir, '.oxlintrc.json');
    writeFileSync(generatedPath, generated?.content || '');
    expect(writer.isBitGenerated(generatedPath)).toBe(true);
    expect(readFileSync(generatedPath, 'utf8')).toContain(
      '// bit-generated-oxlint-config'
    );
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
});

it('recognizes every currently supported Oxlint config filename', () => {
  const writer = new OxlintConfigWriter('OxlintConfigWriter', '/tmp/config');
  expect(writer.patterns).toEqual([
    '**/.oxlintrc.{json,jsonc}',
    '**/oxlint.config.{ts,mts}',
  ]);
});
